import{automaticTileRule}from'./movement-defaults.js';
export const RULES={original:{name:'Keep ROM rule',color:'#607b75'},walk:{name:'Walkable',color:'#48a66d'},block:{name:'Blocked',color:'#d45a5a'},behind:{name:'Walk behind',color:'#9465ce'},water:{name:'Water / Surf',color:'#4a9ed5'},...Object.fromEntries(Object.entries(LEDGES).map(([id,l])=>['ledge_'+id,{name:l.name+' ledge',color:'#bc7a41'}]))};
export function sourceWord(map,x,y){return sourceBlock(map,x,y)??0x3000;}
export function movementAt(map,x,y,{openGates=new Set(),fieldState=null,ignoreFieldObjects=false,objects=null}={}){
 if(!inBounds(map,x,y))return{mode:'block',collision:1,elevation:3};
 const i=y*map.width+x,manual=map.movement?.[i],rule=manual||automaticTileRule(map,x,y),word=sourceWord(map,x,y),mode=rule?.mode||'original';
 let collision=rule?.collision??(mode==='block'||mode.startsWith('ledge_')?1:['walk','behind','water'].includes(mode)?0:(word>>>10)&3),elevation=rule?.elevation??(mode==='water'?1:(word>>>12)&15),behind=mode==='behind',behavior=rule?.behavior??(mode.startsWith('ledge_')?LEDGES[mode.slice(6)]?.behavior:mode==='water'?0x10:mode==='original'?null:0),objectRule=false,objectBlocked=false;const layerType=mode==='behind'?2:rule?.layerType??nativeLayerType(map,x,y);
 for(const o of objects||map.objects){if(x<o.x||y<o.y||x>=o.x+o.w||y>=o.y+o.h||!o.collisionChoice||o.collisionChoice==='keep')continue;let solid=false,foreground=false;
  if(o.collisionChoice==='mask'){const value=o.collisionMask?.[Math.floor(y-o.y)]?.[Math.floor(x-o.x)];if(value===null||value===undefined)continue;solid=value===1;foreground=value===2||o.collisionMaskVersion!==2&&!!o.building&&!solid&&y<o.y+o.h-1;}
  if(o.collisionChoice==='solid')solid=true;
  if(o.collisionChoice==='base'){const e=o.building?.entrance,door=e&&x===o.x+e.x&&y===o.y+e.y;solid=y>=Math.ceil(o.y+o.h)-1&&!door;foreground=!solid&&!door;}
  if(o.collisionChoice==='behind')foreground=true;
  if(o.collisionChoice==='building'){const e=o.building?.entrance;solid=!(e&&x===o.x+e.x&&y===o.y+e.y);}
  if(o.collisionChoice==='footprint'){const f=o.footprint||{x:0,y:o.h-1,w:o.w,h:1},e=o.building?.entrance,door=e&&x===o.x+e.x&&y===o.y+e.y;solid=!door&&x>=o.x+f.x&&x<o.x+f.x+f.w&&y>=o.y+f.y&&y<o.y+f.y+f.h;foreground=!solid&&!door;}
  objectRule=true;objectBlocked||=solid;behind||=foreground;
 }
 if(objectRule){collision=objectBlocked?1:0;behavior=0;}
 for(const n of map.markers)if(n.runtime?.enabled!==false&&n.runtime?.blocksMovement&&n.x===x&&n.y===y){collision=1;behavior=0;}
 if(map.wallCells?.[i]){collision=1;behavior=0;}
 for(const gate of map.gates||[]){const r=gateRule(gate,x,y,openGates.has(gate.id)||gate.startOpen);if(!r)continue;behind||=r.behind;if(r.collision!==null){collision=r.collision;behavior=0;}}
 if(manual?.overrideObjects){collision=manual.collision??(mode==='block'||mode.startsWith('ledge_')?1:0);behind=mode==='behind';behavior=manual.behavior??(mode==='water'?0x10:mode.startsWith('ledge_')?LEDGES[mode.slice(6)]?.behavior:0);objectBlocked=false;}
 const fieldObject=ignoreFieldObjects?null:fieldAt(map,x,y,fieldState);if(fieldObject||!ignoreFieldObjects&&map.markers.some(n=>{const p=fieldState?.actorPositions?.get(n.id)||n;return n.npc&&n.runtime?.enabled!==false&&!p.hidden&&p.x===x&&p.y===y;}))collision=1;return{mode,collision,elevation,behavior,behind,objectBlocked,fieldObject,layerType,nativeForeground:(map.rom?.metatileLayers||2)===2&&(layerType===0||layerType===2)};
}
export function setMovement(map,x,y,rule){if(!inBounds(map,x,y))return;assertAssemblyEdit(map,x,y);map.movement??=Array(map.width*map.height).fill(null);map.movement[y*map.width+x]=rule.mode==='original'?null:{...rule};}
export function createMovementQuery(map,options={}){
 const index=new Map(),empty=[],context={...options};
 for(const o of map.objects){if(!o.collisionChoice||o.collisionChoice==='keep')continue;for(let y=Math.max(0,Math.floor(o.y));y<Math.min(map.height,Math.ceil(o.y+o.h));y++)for(let x=Math.max(0,Math.floor(o.x));x<Math.min(map.width,Math.ceil(o.x+o.w));x++){const key=y*map.width+x;if(!index.has(key))index.set(key,[]);index.get(key).push(o);}}
 return (x,y)=>{context.objects=index.get(y*map.width+x)||empty;return movementAt(map,x,y,context);};
}
const N=[[0,-1,1],[1,0,2],[0,1,4],[-1,0,8]];
export function wallMask(map,x,y,id){let mask=0;for(const[dx,dy,bit]of N)if(inBounds(map,x+dx,y+dy)&&map.wallCells?.[(y+dy)*map.width+x+dx]?.styleId===id)mask|=bit;return mask;}
export function wallTile(map,x,y,style){let mask=wallMask(map,x,y,style.id);if(style.axis==='horizontal')mask&=10;const role=map.wallCells?.[y*map.width+x]?.role,v=style.roles?.[role]||style.variants[mask]||style.variants[0];return{assetId:style.assetId,sx:v.sx,sy:v.sy,sw:style.sw||16,sh:style.sh||16,x,y:y-(style.sh||16)/16+1,w:(style.sw||16)/16,h:(style.sh||16)/16};}
export function paintWall(map,x,y,style,erase=false){if(!inBounds(map,x,y))return;assertAssemblyEdit(map,x,y);map.wallCells??=Array(map.width*map.height).fill(null);map.wallCells[y*map.width+x]=erase?null:{styleId:style.id};}
export function addPortal(project,from,to,{twoWay=true,label='Portal',style='step'}={}){for(const end of[from,to]){const map=project.maps.find(m=>m.id===end.mapId);if(!map||!inBounds(map,end.x,end.y))throw Error('Choose a tile inside each map.');}if(from.mapId===to.mapId&&from.x===to.x&&from.y===to.y)throw Error('Choose two different portal tiles.');const link={id:uid(),from:{...from},to:{...to},kind:'warp',twoWay,label,runtime:{type:'portal',style}};project.links.push(link);return link;}
export function portalAt(project,mapId,x,y){for(const l of project.links){if(!l.runtime)continue;if(l.from.mapId===mapId&&l.from.x===x&&l.from.y===y)return{link:l,to:l.to};if(l.twoWay&&l.to.mapId===mapId&&l.to.x===x&&l.to.y===y)return{link:l,to:l.from};}return null;}
export function wrapDialogue(text,max=28){if(typeof text!=='string'||!text.trim())throw Error('Write the dialogue first.');if(text.length>4000)throw Error('Keep one interaction under 4,000 characters.');const paragraphs=text.replace(/\r/g,'').replace(/\\n/g,'\n').replace(/\\p/g,'\n\n').split(/\n\n+/),pages=[];for(const paragraph of paragraphs){const lines=[];for(const line of paragraph.split('\n')){let current='';for(const word of line.split(/\s+/).filter(Boolean)){if(word.length>max)throw Error('A word is too wide for the dialogue box. Add a space or line break.');if(current&&(current+' '+word).length>max){lines.push(current);current=word;}else current=current?current+' '+word:word;}if(current)lines.push(current);}for(let i=0;i<lines.length;i+=2)pages.push(lines.slice(i,i+2).join('\\n'));}return pages.join('\\p').replace(/\$/g,'\\$');}
export function validateWorld(p,assetIds){validateFields(p,assetIds);const fail=s=>{throw Error(s);};for(const m of p.maps){validateEnvironment(m);for(const key of['movement','wallCells'])if(m[key]!==undefined&&(!Array.isArray(m[key])||m[key].length!==m.width*m.height))fail('The world-rule grid has invalid dimensions.');for(const r of m.movement||[])if(r&&(!RULES[r.mode]||r.collision!==undefined&&(!Number.isInteger(r.collision)||r.collision<0||r.collision>3)||r.elevation!==undefined&&(!Number.isInteger(r.elevation)||r.elevation<0||r.elevation>15)||r.behavior!==undefined&&(!Number.isInteger(r.behavior)||r.behavior<0||r.behavior>511)))fail('A movement rule is invalid.');if(m.gates!==undefined&&(!Array.isArray(m.gates)||m.gates.length>64))fail('Too many gates in one map.');for(const g of m.gates||[]){validateGateMasks(g);if(!g||typeof g.id!=='string'||typeof g.closedAssetId!=='string'||!inBounds(m,g.x,g.y)||![g.w,g.h].every(n=>Number.isInteger(n)&&n>=1&&n<=8)||g.x+g.w>m.width||g.y-g.h+1<0||![g.closedAssetId,g.openAssetId].filter(Boolean).every(id=>assetIds.has(id)))fail('A gate has invalid artwork or bounds.');}for(const o of m.objects)if(o.collisionChoice==='mask'&&(!Array.isArray(o.collisionMask)||o.collisionMask.length!==o.h||o.collisionMask.some(row=>!Array.isArray(row)||row.length!==o.w||row.some(v=>v!==0&&v!==1&&v!==2&&v!==null))))fail('A doorway movement mask is invalid.');for(const n of m.markers)if(n.runtime)validateEvent(n,p,m);}for(const l of p.links)if(l.runtime&&(l.runtime.type!=='portal'||!['step','door'].includes(l.runtime.style)||['nativeDoorStyle','nativeReturnDoorStyle'].some(k=>l.runtime[k]!==undefined&&(!Number.isInteger(l.runtime[k])||l.runtime[k]<0||l.runtime[k]>95))||['arrivalFacing','returnFacing'].some(k=>l.runtime[k]!==undefined&&!['auto','north','south','west','east'].includes(l.runtime[k]))))fail('A playable portal is invalid.');for(const g of p.gateStyles||[]){validateGateMasks(g);if(!g||typeof g.id!=='string'||typeof g.name!=='string'||typeof g.closedAssetId!=='string'||![g.w,g.h].every(n=>Number.isInteger(n)&&n>=1&&n<=8)||![g.closedAssetId,g.openAssetId].filter(Boolean).every(id=>assetIds.has(id)))fail('A saved gate template is invalid.');}for(const w of p.wallStyles||[])if(!w||typeof w.id!=='string'||typeof w.name!=='string'||!assetIds.has(w.assetId)||!Array.isArray(w.variants)||w.variants.length!==16||w.variants.some(v=>!v||![v.sx,v.sy].every(n=>Number.isInteger(n)&&n>=0))||![w.sw||16,w.sh||16].every(n=>Number.isInteger(n)&&n>=1&&n<=128))fail('A connected wall style is invalid.');}

export function wallRectangle(map,a,b,style,erase=false){const x0=Math.min(a.x,b.x),x1=Math.max(a.x,b.x),y0=Math.min(a.y,b.y),y1=Math.max(a.y,b.y);if(x1-x0<2||y1-y0<2)throw Error('Draw an enclosure at least 3 × 3 tiles.');for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){if(x!==x0&&x!==x1&&y!==y0&&y!==y1)continue;if(!inBounds(map,x,y))continue;paintWall(map,x,y,style,erase);if(!erase)map.wallCells[y*map.width+x].role=y===y0?(x===x0?'nw':x===x1?'ne':'n'):y===y1?(x===x0?'sw':x===x1?'se':'s'):x===x0?'w':'e';}}
